!function(){"use strict";const e={athirappilly:{title:"Athirappilly Falls",desc:'Kerala\'s largest waterfall at 80 feet, located 5 km downstream from Vazhachal. Known as the "Niagara of India," it features a dramatic vertical plunge and is a popular filming location. Managed as part of the Athirappilly-Vazhachal ecotourism circuit.'},vazhachal:{title:"Vazhachal Falls",desc:"The cascading rapids of the Chalakudy River flowing over rocky terrain in dense forest. Unlike Athirappilly's vertical drop, Vazhachal features inclined cascades creating a series of rapids and pools. More serene and forested experience."},thumboormuzhi:{title:"Thumboormuzhi Dam & Ezhattumukham",desc:"Historic check dam built in 1964 across the Chalakudy River. Features hanging bridge, garden, and the nearby Ezhattumukham Prakriti Gramam nature park with butterfly garden, tree houses, and adventure activities."},sholayar:{title:"Sholayar Dam",desc:"One of Asia's deepest reservoirs surrounded by pristine forests in the Anaimalai range. Built in 1965, it's an engineering marvel offering boating, trekking, and stunning views. Part of the Sholayar forest division."}};document.addEventListener("DOMContentLoaded",()=>{!function(){const a=document.querySelectorAll(".map-marker"),t=document.getElementById("map-info-title"),r=document.getElementById("map-info-desc");t&&r&&a.forEach(a=>{const i=a.dataset.point,n=()=>{const a=e[i];a&&(t.textContent=a.title,r.textContent=a.desc)};a.addEventListener("click",n),a.addEventListener("keydown",e=>{"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),n())})})}(),function(){const e=document.getElementById("vf-section-nav"),a=document.querySelectorAll(".vf-nav-link");if(!e)return;const t=Array.from(a).map(e=>({link:e,section:document.getElementById(e.getAttribute("href").replace("#",""))})).filter(e=>e.section),r=e=>{a.forEach(e=>e.classList.remove("active")),e.classList.add("active")};a.forEach(e=>{e.addEventListener("click",()=>r(e))});const i=new IntersectionObserver(a=>{a.forEach(a=>{if(a.isIntersecting){const t=a.target.id,i=e.querySelector(`[href="#${t}"]`);i&&r(i)}})},{rootMargin:"-40% 0px -50% 0px"});t.forEach(e=>i.observe(e.section))}(),function(){const e=document.querySelectorAll(".reveal");if(!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("visible"));const a=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),a.unobserve(e.target))})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});e.forEach(e=>a.observe(e))}(),window.Journey&&window.Journey.registerSearchItems("frontend/vazhachal-falls-explorer/index.html",[{id:"vazhachal-main",title:"Vazhachal Falls Explorer",description:"Explore Vazhachal Falls on the Chalakudy River in Kerala - cascading rapids, pristine evergreen forests, rich biodiversity, and the complete river journey from Anaimalai Hills to Arabian Sea.",link:"frontend/vazhachal-falls-explorer/index.html"},{id:"vazhachal-ecosystem",title:"Vazhachal Forest Ecosystem",description:"Biodiversity hotspot in the Western Ghats - tropical evergreen forests, endemic primates, 180+ bird species, Asian elephants, and 89 fish species in the Chalakudy River.",link:"frontend/vazhachal-falls-explorer/index.html#ecosystem"},{id:"vazhachal-river",title:"Chalakudy River Journey",description:"The 85 km journey of the Chalakudy River from Anaimalai Hills origin through Sholayar forests, Vazhachal cascades, Athirappilly falls, to the Arabian Sea.",link:"frontend/vazhachal-falls-explorer/index.html#river"}])})}();